sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 leakPos;
uniform float leakSize;
uniform float rotation;
uniform float stretch;
layout(color) uniform half4 colorA;
layout(color) uniform half4 colorB;
layout(color) uniform half4 colorC;
uniform float noiseAmount;
uniform float speed;
uniform float pulse;
uniform float intensity;
uniform float blend;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(float2 p, float oct, float rough) {
    float v = 0.0;
    float a = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 6; i++) {
        if (float(i) >= oct) break;
        v += a * vnoise(p);
        norm += a;
        p = p * 2.03 + float2(11.7, 5.3);
        a *= rough;
    }
    return v / max(norm, 0.0001);
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 uv = coord / size;
    float2 d = rot2((uv - leakPos) * float2(size.x / size.y, 1.0), radians(rotation));
    d.x /= stretch;
    float n = fbm(uv * 3.0 + time * speed, 4.0, 0.5);
    float blob = exp(-pow(length(d) / max(leakSize, 0.01), 1.6) * 2.0);
    blob *= mix(1.0, n * 1.6, noiseAmount);
    blob *= 1.0 - pulse * 0.5 * (0.5 + 0.5 * sin(time * 1.3));
    float k = saturate(n * 1.4 + length(d) * 0.5);
    float3 lc = mix(mix(float3(colorA.rgb), float3(colorB.rgb), saturate(k * 2.0)), float3(colorC.rgb), saturate(k * 2.0 - 1.0));
    float3 layer = lc * blob * intensity;
    float3 o = blendm(s, layer, blend);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
